// Avoid animating width/height or top/left
<motion.div
  animate={{ width: 300, top: 20 }}
  transition={{ duration: 0.3 }}
/>

// Use scale and translate for layout shifts
<motion.div
  animate={{ scaleX: 1.2, y: 20, opacity: 1 }}
  transition={{ duration: 0.3, ease: [0.16, 1, 0.3, 1] }}
/>
